export default {
  id: 'pricing',
  name: 'Pricing',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    // Register the pricing service: id=pricing, instance.total(n) = n * 21
    ctx.register({
      kind: 'service',
      service: {
        id: 'pricing',
        instance: {
          total(n: number): number {
            return n * 21;
          },
        },
      },
    });

    // Register the tool that consumes the service via ctx.inject('service:pricing').value
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'quote_total',
        version: '1.0.0',
        description: 'Quote a total for n units using the pricing service (returns n * 21).',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            n: { type: 'number', description: 'Number of units' },
          },
          required: ['n'],
        },
        outputSchema: {
          type: 'object',
          properties: {
            total: { type: 'number', description: 'Quoted total' },
          },
          required: ['total'],
        },
        async handler(args: unknown) {
          const { n } = args as { n: number };
          const injected = ctx.inject('service:pricing');
          try {
            const service = injected.value as { total?: (value: number) => number } | undefined;
            if (!service || typeof service.total !== 'function') {
              return {
                ok: false,
                error: 'service:pricing is not available',
                failure: { code: 'service_missing', retryable: false, outcome: 'not_started' },
              };
            }
            return { ok: true, data: { total: service.total(n) } };
          } finally {
            injected.stop();
          }
        },
      },
    });
  },
};

